SINA_SMART["anat1-thorax-walls"] = {"lecture":"anat1-thorax-walls","title":"Thorax part 4: thoracic walls and breast","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat1-thorax-walls:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"insufficient-source"},{"id":"anat1-thorax-walls:e0","text":"Bundle: costal groove, between internal and innermost intercostals; VAN.","topic":"Intercostal nerves and arteries","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-walls:e1","text":"Intercostal nerves = ventral rami T1-T11; cutaneous and muscular branches.","topic":"Intercostal nerves and arteries","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-walls:e2","text":"Internal thoracic a. (subclavian) → anterior intercostals, perforators; ends as musculophrenic + superior epigastric.","topic":"Intercostal nerves and arteries","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-walls:e3","text":"Posterior intercostals: first two from supreme intercostal a., rest from aorta.","topic":"Intercostal nerves and arteries","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-walls:e4","text":"Anterior and posterior intercostal arteries anastomose.","topic":"Intercostal nerves and arteries","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-walls:e5","text":"Posterior intercostal veins: upper two → brachiocephalic; lower nine → azygos → SVC.","topic":"Veins and lymphatics","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-walls:e6","text":"Nodes: parasternal, intercostal, phrenic.","topic":"Veins and lymphatics","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-walls:e7","text":"Breast: ribs 2-6, sternum to midaxillary line, on pectoralis major and serratus anterior; retromammary space.","topic":"The breast","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1dklln9":"a","jth0ej":"a","17xkl7i":"a","1hycpf9":"a","1277gls":"a","cq9ne0":"a","nnr7l3":"a","v4cdu3":"a","rteffl":"a","1tvps1a":"a"},"mapCounts":{"verified":0,"auto":10,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat1-thorax-walls:s0":{"s":0,"u":["The thoracic wall (vertebrae, ribs, sternum, intercostal muscles) is supplied by neurovascular bundles running in each intercostal space, anastomosing arteries from the subclavian artery and aorta, veins to the brachiocephalic and azygos systems, and lymph nodes that also drain the breast."],"dp":[]},"anat1-thorax-walls:e0":{"s":1,"u":["Bundle: costal groove, between internal and innermost intercostals; VAN.","In each space the bundle runs in the costal groove of the upper rib, between the internal and innermost intercostals: vein, artery, nerve from top to bottom."],"dp":[]},"anat1-thorax-walls:e1":{"s":1,"u":["Intercostal nerves = ventral rami T1-T11; cutaneous and muscular branches.","Intercostal nerves are the ventral rami of T1-T11 (T12 = subcostal nerve), named by their space, giving lateral and anterior cutaneous (sensory) and muscular (motor) branches."],"dp":[{"h":"Note","t":"Intercostal nerves = ventral rami T1-T11 (T12 = subcostal). Dermatomes: T4 nipple , T10 umbilicus ."}]},"anat1-thorax-walls:e2":{"s":1,"u":["Internal thoracic a. (subclavian) → anterior intercostals, perforators; ends as musculophrenic + superior epigastric.","Arteries : the internal thoracic artery (from the subclavian; inside the cage just lateral to the sternum) gives the anterior intercostal arteries and the anterior perforating arteries (pectoralis major, skin; the 2nd-4th give medial mammary branches) and ends as the musculophrenic (anterior intercostals of spaces 7-9, pierces the diaphragm) and superior epigastric arteries."],"dp":[{"h":"Note","t":"Internal thoracic artery (from subclavian) runs just lateral to the sternum; ends as musculophrenic and superior epigastric arteries (which anastomose with the inferior epigastric in the rectus sheath)."}]},"anat1-thorax-walls:e3":{"s":1,"u":["Posterior intercostals: first two from supreme intercostal a., rest from aorta.","Posterior intercostal arteries : the first two from the supreme intercostal artery (costocervical trunk), the rest from the thoracic aorta ; they anastomose with the anterior ones."],"dp":[{"h":"Note","t":"Posterior intercostal arteries : first two from the supreme intercostal (costocervical trunk), rest from the aorta . Veins: lower ones → azygos → SVC."}]},"anat1-thorax-walls:e4":{"s":1,"u":["Anterior and posterior intercostal arteries anastomose.","Posterior intercostal arteries : the first two from the supreme intercostal artery (costocervical trunk), the rest from the thoracic aorta ; they anastomose with the anterior ones.","Arteries : the internal thoracic artery (from the subclavian; inside the cage just lateral to the sternum) gives the anterior intercostal arteries and the anterior perforating arteries (pectoralis major, skin; the 2nd-4th give medial mammary branches) and ends as the musculophrenic (anterior intercostals of spaces 7-9, pierces the diaphragm) and superior epigastric arteries."],"dp":[]},"anat1-thorax-walls:e5":{"s":2,"u":["Posterior intercostal veins: upper two → brachiocephalic; lower nine → azygos → SVC.","Posterior intercostal veins : the upper two → brachiocephalic veins; the lower nine → azygos system → superior vena cava.","Internal thoracic vein → brachiocephalic vein."],"dp":[]},"anat1-thorax-walls:e6":{"s":2,"u":["Nodes: parasternal, intercostal, phrenic.","Lymph nodes: parasternal (along the internal thoracic artery; medial breast, intercostal spaces, diaphragm, upper abdominal wall → junction of internal jugular and subclavian veins), intercostal (near rib heads; → cisterna chyli or thoracic duct), phrenic (on the diaphragm; pericardium, diaphragm, liver → mediastinal nodes)."],"dp":[]},"anat1-thorax-walls:e7":{"s":3,"u":["Breast: ribs 2-6, sternum to midaxillary line, on pectoralis major and serratus anterior; retromammary space.","It lies on the deep fascia of pectoralis major and serratus anterior , separated by the loose retromammary space , which gives it mobility.","Secretory glandular tissue, superficial fascia and skin in the pectoral region; the mammary gland overlies ribs 2 to 6 , between the sternum and the midaxillary line , within the superficial fascia, surrounded by fat that determines size and shape; it enlarges during the menstrual cycle and pregnancy."],"dp":[{"h":"Note","t":"Breast : ribs 2-6, sternum to midaxillary line, on pectoralis major/serratus anterior; axillary tail reaches the axilla. Lymph: ~75% axillary , medial part parasternal ."},{"h":"Clinical","t":"Cancer invading the suspensory (Cooper's) ligaments causes skin dimpling; blocked lymphatics cause peau d'orange . Fixation to pectoralis major suggests deep invasion (retromammary space lost)."}]}},"meta":{"1dklln9":{"a":"recall","vg":"anat1-thorax-walls:e1/recall/1"},"jth0ej":{"a":"recall","vg":"anat1-thorax-walls:e2/recall/1"},"17xkl7i":{"a":"recall","vg":"anat1-thorax-walls:e2/recall/2"},"1hycpf9":{"a":"recall","vg":"anat1-thorax-walls:e3/recall/1"},"1277gls":{"a":"recall","vg":"anat1-thorax-walls:e2/recall/3"},"cq9ne0":{"a":"recall","vg":"anat1-thorax-walls:e5/recall/1"},"nnr7l3":{"a":"recall","vg":"anat1-thorax-walls:e6/recall/1"},"v4cdu3":{"a":"recall","vg":"anat1-thorax-walls:e7/recall/1"},"rteffl":{"a":"recall","vg":"anat1-thorax-walls:e7/recall/2"},"1tvps1a":{"a":"recall","vg":"anat1-thorax-walls:e0/recall/1"}},"explRev":"a9689543a685"};
